type ListRolloutLaneMembersRow struct {
	LaneID           int64
	DeviceID         int64
	DeviceIdentifier string
	Model            string
	FirmwareVersion  string
}

// All lane members for an org with model and currently reported firmware.
func (q *Queries) ListRolloutLaneMembers(ctx context.Context, orgID int64) ([]ListRolloutLaneMembersRow, error) {
	rows, err := q.query(ctx, q.listRolloutLaneMembersStmt, listRolloutLaneMembers, orgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListRolloutLaneMembersRow
	for rows.Next() {
		var i ListRolloutLaneMembersRow
		if err := rows.Scan(
			&i.LaneID,
			&i.DeviceID,
			&i.DeviceIdentifier,
			&i.Model,
			&i.FirmwareVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

